/**
 * @brief Шаблон метода кодирования
 *
 * @tparam T тип возвращаемого результата
 *
 */
template <typename T>
/**
 * @brief Метод финализации контекста шифрования
 *
 * @param buffer буфер куда следует положить результат
 * @return       результат финализации
 *
 */
bool awh::Crypto::finalize(T & buffer) noexcept {
	// Если объект собран не был
	if(!this->ready())
		// Выходим из метода
		return false;
	// Переменная результата
	bool result = false;
	/**
	 * Размер поданного буфера запоминается до всякой работы: завершение буфер
	 * лишь дополняет (4.34), и при отказе трогать оно вправе только то, что само
	 * же и дописало
	 */
	// Размер поданного буфера до работы завершения
	const size_t origin = buffer.size();
	/**
	 * Выполняем отлов ошибок
	 */
	try {
		// Получаем состояние объекта
		state_t & state = (* this->_params.state);
		// Если поток шифрования заведён
		if((result = state.stream.ready())){
			/**
			 * Признак проверки подлинности снимается до сброса стейта: сброс
			 * обнуляет направление работы, и сообщение об отказе читало уже
			 * сброшенное значение - подделка объявлялась сбоем завершения
			 */
			// Признак того, что отказ завершения означает подделку шифротекста
			const bool tampered = ((state.event == event_t::DECODE) && (state.mode == mode_t::GCM));
			// Буфер завершающих данных потока
			vector <uint8_t> ending;
			/**
			 * Завершение потока ведёт поточная обёртка: при расшифровке она
			 * сличает удержанную имитовставку GCM и отказывает при подделке,
			 * при зашифровании дописывает имитовставку в хвост; вектор
			 * инициализации, не выписанный ни одной порцией, уходит здесь же
			 */
			// Выполняем завершение работы шифрования
			if(!(result = state.stream.finish(ending))){
				// Снимаем с буфера то, что дописала работа завершения
				driver::truncate(buffer, origin, (state.event == event_t::DECODE));
				// Выполняем сброс стейта шифрования
				state.reset();
				/**
				 * Отказ завершения при расшифровке в режиме с проверкой подлинности
				 * означает подделку шифротекста, а не сбой
				 */
				/**
				 * Если включён режим отладки
				 */
				#if defined(DEBUG_MODE)
					// Записываем ошибку в лог
					log::debug((tampered ? "Authentication of the ciphertext failed" : "Error cipher final"), __PRETTY_FUNCTION__, {}, log::flag_t::WARNING);
				/**
				 * Если режим отладки не включён
				 */
				#else
					// Записываем ошибку в лог
					log::print((tampered ? "Authentication of the ciphertext failed" : "Error cipher final"), log::flag_t::WARNING);
				#endif
				// Выходим из метода
				return result;
			}
			/**
			 * Завершающие данные дописываются в конец поданного буфера, а не
			 * вставляются в начало: работа завершения буфер лишь дополняет,
			 * а что в нём лежало до неё - дело вызывающего
			 */
			// Дописываем завершающие данные потока в конец поданного буфера
			buffer.insert(buffer.end(), ending.begin(), ending.end());
			/**
			 * Успешно завершённый поток снимает приметы одного лишь потока, а ключ
			 * удерживает: без этого всякий новый поток выводил бы его заново - сто
			 * тысяч итераций, 6.4 мс на замере, - тогда как разовое шифрование ключ
			 * удерживало всегда. Отказы же сбрасывают стейт целиком - см. 4.26
			 */
			// Выполняем сброс примет одного лишь потока
			state.renew();
		/**
		 * Завершение потока, не заведённого вовсе, называет свою причину: прежде оно
		 * отказывало молча, а отказ этот от прочих отличить нечем - буфер завершение
		 * не трогает, и признак остаётся единственной приметой
		 */
		// Если контекст потокового шифрования не заведён
		} else {
			/**
			 * Если включён режим отладки
			 */
			#if defined(DEBUG_MODE)
				// Записываем ошибку в лог
				log::debug("Stream is not initialized", __PRETTY_FUNCTION__, {buffer.size()}, log::flag_t::WARNING);
			/**
			 * Если режим отладки не включён
			 */
			#else
				// Записываем ошибку в лог
				log::print("Stream is not initialized", log::flag_t::WARNING);
			#endif
		}
	/**
	 * Если возникает ошибка
	 */
	} catch(const exception & error) {
		/**
		 * Признак работы гасится, буфер затирается, а стейт сбрасывается: признак
		 * взводился наперёд, по одному лишь наличию контекста, и сбой посреди
		 * завершения выдавался бы за успех - при живом контексте и открытом тексте,
		 * подлинности не прошедшем
		 */
		// Снимаем признак успешно выполненной работы
		result = false;
		// Снимаем с буфера то, что дописала работа завершения
		driver::truncate(buffer, origin, (this->_params.state->event == event_t::DECODE));
		// Выполняем сброс стейта AES-шифрования
		this->_params.state->reset();
		/**
		 * Если включён режим отладки
		 */
		#if defined(DEBUG_MODE)
			// Записываем ошибку в лог
			log::debug("%s", __PRETTY_FUNCTION__, {}, log::flag_t::CRITICAL, error.what());
		/**
		 * Если режим отладки не включён
		 */
		#else
			// Записываем ошибку в лог
			log::print("%s", log::flag_t::CRITICAL, error.what());
		#endif
	}
	// Возвращаем результат работы функции
	return result;
}
/**
 * @brief Явный специализированный шаблон метода финализации контекста шифрования
 *
 */
template bool awh::Crypto::finalize(string &) noexcept;
/**
 * @brief Явный специализированный шаблон метода финализации контекста шифрования
 *
 */
template bool awh::Crypto::finalize(vector <char> &) noexcept;
/**
 * @brief Явный специализированный шаблон метода финализации контекста шифрования
 *
 */
template bool awh::Crypto::finalize(vector <uint8_t> &) noexcept;
/**
 * @brief Метод инициализации контекста шифрования
 *
 * @param event  событие шифрования (ENCODE, DECODE)
 * @param hash   тип хэш-суммы
 * @param cipher тип шифрования (BASE64, AES128, AES192, AES256)
 * @return       результат инициализации
 *
 */
bool awh::Crypto::initialize(const event_t event, const hash_t hash, const cipher_t cipher) noexcept {
	// Если объект собран не был
	if(!this->ready())
		// Выходим из метода
		return false;
	// Переменная результата
	bool result = false;
	/**
	 * Кодирование BASE64 потоком не выполняется и отвергается здесь по имени, а не
	 * в глубине заведения ключа: там оно попадало в отбор разрядности шифра, своей
	 * разрядности среди них не находило и отвергалось как шифрование неизвестного
	 * вида. Потоком оно не выполняется потому, что записью BASE64 три октета входа
	 * дают четыре знака выхода: разрежь поток не по трём октетам - и стыки порций
	 * дадут запись, которую обратно не разобрать
	 */
	// Если работа заводится кодированием BASE64
	if(cipher == cipher_t::BASE64){
		/**
		 * Если включён режим отладки
		 */
		#if defined(DEBUG_MODE)
			// Записываем ошибку в лог
			log::debug("BASE64 encoding is performed by a single call and has no stream", __PRETTY_FUNCTION__, {static_cast <uint16_t> (hash), static_cast <uint16_t> (cipher)}, log::flag_t::CRITICAL);
		/**
		 * Если режим отладки не включён
		 */
		#else
			// Записываем ошибку в лог
			log::print("BASE64 encoding is performed by a single call and has no stream", log::flag_t::CRITICAL);
		#endif
		// Выходим из метода
		return result;
	}
	/**
	 * Выполняем отлов ошибок
	 */
	try {
		// Если пароль установлен
		if(!this->_params.password.empty()){
			// Получаем состояние объекта
			state_t & state = (* this->_params.state);
			{
				/**
				 * Заведённый прежде контекст шифрования сбрасывается, а не отменяет
				 * работу: повторная инициализация иначе всегда отвечала отказом, и
				 * сменить направление либо шифр после первого раза было нечем
				 */
				/**
				 * Ключ, выведенный теми же приметами, выводится не заново, а удерживается:
				 * вывод его стоит ста тысяч итераций, и всякий новый поток платил их сполна.
				 * Разовое шифрование ключ удерживало и прежде, поток же - нет, и та же самая
				 * работа обходилась ему в тысячи раз дороже. Пароль, соль и число итераций
				 * своими установками стейт сбрасывают, и уцелевший ключ означает, что выведен
				 * он из них же (5.21)
				 */
				/**
				 * Если контекст шифрования уцелел, прежний поток завершён не был
				 *
				 * @details Завершение потока состояние сбрасывает, оттого уцелевший
				 *          контекст означает поток, брошенный на середине. Сброс его
				 *          законен и работу не отменяет, но молчать о нём нельзя:
				 *          вызывающая сторона, забывшая завершить поток, получала бы
				 *          верную работу нового потока и никакого признака того, что
				 *          написанное прежде пропало. Оглашается тем же словом, что и
				 *          у потока подписи (5а.18)
				 */
				if(state.stream.ready()){
					/**
					 * Если включён режим отладки
					 */
					#if defined(DEBUG_MODE)
						// Записываем предупреждение в лог
						log::debug("Unfinished stream is discarded by the new initialization", __PRETTY_FUNCTION__, {static_cast <uint16_t> (event), static_cast <uint16_t> (cipher)}, log::flag_t::WARNING);
					/**
					 * Если режим отладки не включён
					 */
					#else
						// Записываем предупреждение в лог
						log::print("Unfinished stream is discarded by the new initialization", log::flag_t::WARNING);
					#endif
				}
				// Определяем, выведен ли ключ теми же приметами
				const bool derived = (!state.key.empty() && (state.hash == hash) &&
				                      (state.cipher == cipher) && (state.mode == this->_params.mode) &&
				                      (state.rounds == this->_params.rounds));
				// Если ключ выведен теми же приметами
				if(derived)
					// Выполняем сброс примет одного лишь потока
					state.renew();
				// Выполняем сброс стейта AES-шифрования
				else state.reset();
				// Если инициализация ключей не выполнена
				if(!derived && !driver::cipher(cipher, this->_params.mode, hash, this->_params.password, this->_params.salt, this->_params.rounds, state)){
					/**
					 * Если включён режим отладки
					 */
					#if defined(DEBUG_MODE)
						// Записываем ошибку в лог
						log::debug("Unable to initialize AES cipher for encoding data", __PRETTY_FUNCTION__, {static_cast <uint16_t> (hash), static_cast <uint16_t> (cipher)}, log::flag_t::CRITICAL);
					/**
					 * Если режим отладки не включён
					 */
					#else
						// Записываем ошибку в лог
						log::print("Unable to initialize AES cipher for encoding data", log::flag_t::CRITICAL);
					#endif
					// Выходим из метода
					return result;
				}
				// Направление потока шифрования
				nts::cipher::direction_t direction = nts::cipher::direction_t::NONE;
				/**
				 * Определяем событие кодирование или декодирование
				 */
				switch(static_cast <uint8_t> (event)){
					// Если производится кодирование данных
					case static_cast <uint8_t> (event_t::ENCODE):
						// Устанавливаем направление зашифрования
						direction = nts::cipher::direction_t::ENCRYPT;
					break;
					// Если производится декодирование данных
					case static_cast <uint8_t> (event_t::DECODE):
						// Устанавливаем направление расшифрования
						direction = nts::cipher::direction_t::DECRYPT;
					break;
					// Если направление работы не задано
					default: {
						/**
						 * Направление, разбору не знакомое, отменяет инициализацию:
						 * поток без направления не заводится и работу не продолжает
						 */
						// Выполняем сброс стейта шифрования
						state.reset();
						/**
						 * Если включён режим отладки
						 */
						#if defined(DEBUG_MODE)
							// Записываем ошибку в лог
							log::debug("Direction of the stream cipher is not set", __PRETTY_FUNCTION__, {static_cast <uint16_t> (cipher), static_cast <uint16_t> (event)}, log::flag_t::CRITICAL);
						/**
						 * Если режим отладки не включён
						 */
						#else
							// Записываем ошибку в лог
							log::print("Direction of the stream cipher is not set", log::flag_t::CRITICAL);
						#endif
						// Выходим из метода
						return result;
					}
				}
				// Определяем режим потока по режиму блочного шифрования
				const nts::cipher::regime_t regime = ((this->_params.mode == crypto_t::mode_t::GCM) ? nts::cipher::regime_t::GCM : nts::cipher::regime_t::FEEDBACK);
				/**
				 * Заводим поточную обёртку шифрования: вектор инициализации при
				 * зашифровании вырабатывается из энтропии и уходит первым в выход,
				 * при расшифровании копится из головы потока; имитовставку GCM
				 * обёртка ведёт сама, дополнение блока потоковым режимам не нужно
				 */
				// Выполняем заведение потока шифрования
				if(!(result = state.stream.start(direction, state.block(), regime))){
					/**
					 * Стейт сбрасывается наравне с прочими отказами заведения потока:
					 * ключ к этой поре уже выведен, и состояние «ключ есть, потока
					 * нет» расходилось бы с прочими отказами (4.26)
					 */
					// Выполняем сброс стейта шифрования
					state.reset();
					/**
					 * Если включён режим отладки
					 */
					#if defined(DEBUG_MODE)
						// Записываем ошибку в лог
						log::debug("Error during AES context initialization", __PRETTY_FUNCTION__, {static_cast <uint16_t> (cipher), static_cast <uint16_t> (event)}, log::flag_t::CRITICAL);
					/**
					 * Если режим отладки не включён
					 */
					#else
						// Записываем ошибку в лог
						log::print("Error during AES context initialization", log::flag_t::CRITICAL);
					#endif
					// Выходим из метода
					return result;
				}
				// Запоминаем направление работы потокового шифрования
				state.event = event;
			}
		/**
		 * Если пароль шифрования не установлен
		 */
		} else {
			/**
			 * Если включён режим отладки
			 */
			#if defined(DEBUG_MODE)
				// Записываем ошибку в лог
				log::debug("Password of the stream cipher is not set", __PRETTY_FUNCTION__, {static_cast <uint16_t> (hash), static_cast <uint16_t> (cipher)}, log::flag_t::CRITICAL);
			/**
			 * Если режим отладки не включён
			 */
			#else
				// Записываем ошибку в лог
				log::print("Password of the stream cipher is not set", log::flag_t::CRITICAL);
			#endif
		}
	/**
	 * Если возникает ошибка
	 */
	} catch(const exception & error) {
		/**
		 * Стейт сбрасывается наравне с прочими отказами заведения потока (4.26,
		 * 4.31): сбой отведения памяти мог застать работу после заведения контекста
		 * и вывода ключа - поток остался бы заведённым наполовину
		 */
		// Снимаем признак успешно выполненной работы
		result = false;
		// Выполняем сброс стейта AES-шифрования
		this->_params.state->reset();
		/**
		 * Если включён режим отладки
		 */
		#if defined(DEBUG_MODE)
			// Записываем ошибку в лог
			log::debug("%s", __PRETTY_FUNCTION__, {static_cast <uint16_t> (hash), static_cast <uint16_t> (cipher)}, log::flag_t::CRITICAL, error.what());
		/**
		 * Если режим отладки не включён
		 */
		#else
			// Записываем ошибку в лог
			log::print("%s", log::flag_t::CRITICAL, error.what());
		#endif
	}
	// Возвращаем результат работы функции
	return result;
}
/**
 * @brief Шаблон метода кодирования
 *
 * @tparam T тип возвращаемого результата
 *
 */
template <typename T>
/**
 * @brief Метод кодирования
 *
 * @param buffer буфер данных для шифрования
 * @param hash   тип хэш-суммы
 * @param cipher тип шифрования (BASE64, AES128, AES192, AES256)
 * @return       результат кодирования
 *
 */
auto awh::Crypto::encrypt(string_view buffer, const hash_t hash, const cipher_t cipher) const noexcept -> T {
	// Выполняем кодирование
	return this->encrypt <T> (buffer.data(), buffer.size(), hash, cipher);
}
/**
 * @brief Явный специализированный шаблон метода кодирования данных из строки с выводом результата в строку
 *
 */
template string awh::Crypto::encrypt(string_view, const hash_t, const cipher_t) const noexcept;
/**
 * @brief Явный специализированный шаблон метода кодирования данных из строки с выводом результата в буфер
 *
 */
template vector <char> awh::Crypto::encrypt(string_view, const hash_t, const cipher_t) const noexcept;
/**
 * @brief Явный специализированный шаблон метода кодирования данных из строки с выводом результата в бинарный буфер
 *
 */
template vector <uint8_t> awh::Crypto::encrypt(string_view, const hash_t, const cipher_t) const noexcept;
/**
 * @brief Шаблон метода кодирования
 *
 * @tparam A тип возвращаемого результата
 * @tparam B тип буфера данных
 *
 */
template <typename A, typename B>
/**
 * @brief Метод кодирования
 *
 * @param buffer буфер данных для шифрования
 * @param hash   тип хэш-суммы
 * @param cipher тип шифрования (BASE64, AES128, AES192, AES256)
 * @return       результат кодирования
 *
 */
auto awh::Crypto::encrypt(const B & buffer, const hash_t hash, const cipher_t cipher) const noexcept -> A {
	// Выполняем кодирование
	return this->encrypt <A> (buffer.data(), buffer.size(), hash, cipher);
}
/**
 * @brief Явный специализированный шаблон метода кодирования данных из строки с выводом результата в строку
 *
 */
template string awh::Crypto::encrypt(const string &, const hash_t, const cipher_t) const noexcept;
